"use client";

import React, { useState, useEffect, use } from "react";
import dynamic from "next/dynamic";
import Link from "next/link";
import { 
  ArrowLeft, Activity, List, Settings, 
  AlertTriangle, CheckCircle2, Phone, Upload, Map as MapIcon, Router as RouterIcon, Cpu, Link as LinkIcon, X
} from "lucide-react";

const MapaTopografico = dynamic(
  () => import("@/components/clientes/MapaTopografico"),
  { ssr: false, loading: () => <div className="w-full h-full bg-gray-50 flex items-center justify-center">Cargando...</div> }
);

interface ClientePageProps {
  params: Promise<{ id: string }>;
}

export default function ClienteDetalle({ params }: ClientePageProps) {
  const { id: clienteIdStr } = use(params);
  const clienteId = parseInt(clienteIdStr);
  
  const [activeTab, setActiveTab] = useState<'resumen' | 'inventario' | 'administrativo'>('inventario'); // Por defecto en inventario para probar
  const [cliente, setCliente] = useState<any>(null);

  // Estados para asignación
  const [nodoAAsignar, setNodoAAsignar] = useState<any>(null);

  useEffect(() => {
    cargarDatos();
  }, [clienteId]);

  const cargarDatos = () => {
    fetch(`http://localhost:3001/api/mapa/cliente/${clienteId}`)
      .then(res => res.json())
      .then(data => {
        if (!data.error) setCliente(data);
      })
      .catch(err => console.error("Error obteniendo cliente:", err));
  };

  // Procesamiento de listas
  const sectores = cliente?.sectores || [];
  const gateways = cliente?.gateways || [];
  
  // Nodos Asignados (Tienen sectorId)
  const nodosAsignados = sectores.flatMap((s: any) => 
    s.nodos.map((n: any) => ({ ...n, sectorNombre: s.nombre }))
  );
  
  // Nodos Huérfanos (Aparecieron en la red pero no tienen sector. Por ahora los simulamos filtrando, luego el backend nos los dará)
  // Nota: Asumiremos que el backend enviará un array "nodosHuerfanos" en el futuro.
  const nodosHuerfanos = cliente?.nodosHuerfanos || [
    { id: 'AGV-NUEVO-01', estado: 'ACTIVO', bateria: 100 } // Dato de prueba para que veas la UI
  ];

  const nodosAlerta = nodosAsignados.filter((n: any) => n.estado === 'ALERTA');
  const gatewaysActivos = gateways.filter((gw: any) => gw.estado === 'ACTIVO').length;

  return (
    <div className="flex flex-col gap-6 h-[calc(100vh-2rem)] relative">
      
      {/* Cabecera */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link href="/clientes" className="p-2 hover:bg-gray-100 rounded-lg transition-colors text-gray-500 hover:text-gray-900">
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-gray-900">{cliente?.nombre || 'Cargando...'}</h1>
            <p className="text-sm text-gray-500">ID Cliente: CLI-{clienteId}</p>
          </div>
        </div>
        <div className="flex gap-2">
          <span className={`px-3 py-1.5 rounded-lg text-sm font-semibold flex items-center gap-2 ${gatewaysActivos > 0 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
            <span className={`w-2 h-2 rounded-full ${gatewaysActivos > 0 ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></span>
            {gatewaysActivos} Gateway(s) Online
          </span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 flex-1 min-h-[600px]">
        
        {/* Mapa Satelital */}
        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden relative">
          <MapaTopografico clienteId={clienteId} />
        </div>

        {/* Panel Lateral */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 flex flex-col h-full overflow-hidden">
          
          <div className="flex border-b border-gray-100">
            {['resumen', 'inventario', 'administrativo'].map((tab) => (
              <button 
                key={tab}
                onClick={() => setActiveTab(tab as any)}
                className={`flex-1 py-4 text-sm font-medium border-b-2 flex justify-center items-center gap-2 transition-colors capitalize ${
                  activeTab === tab ? 'border-agrogreen-500 text-agrogreen-700 bg-agrogreen-50/50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
                }`}
              >
                {tab === 'resumen' && <Activity className="w-4 h-4" />}
                {tab === 'inventario' && <List className="w-4 h-4" />}
                {tab === 'administrativo' && <Settings className="w-4 h-4" />}
                {tab}
              </button>
            ))}
          </div>

          <div className="flex-1 overflow-y-auto p-4 bg-gray-50/30">
            
            {/* TAB: INVENTARIO Y DESPLIEGUE */}
            {activeTab === 'inventario' && (
              <div className="space-y-6 animate-in fade-in duration-300">
                
                {/* SECCIÓN 1: Gateways */}
                <div className="space-y-3">
                  <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider flex items-center gap-2">
                    <RouterIcon className="w-4 h-4" /> Gateways de Enlace
                  </h3>
                  {gateways.map((gw: any) => (
                    <div key={gw.id} className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm flex justify-between items-center">
                      <div>
                        <p className="font-bold text-gray-800 text-sm">{gw.nombre || gw.id}</p>
                        <p className="text-xs text-gray-500">Antena Central</p>
                      </div>
                      <span className="bg-blue-100 text-blue-700 px-2 py-1 rounded text-xs font-bold">ACTIVO</span>
                    </div>
                  ))}
                  {gateways.length === 0 && <p className="text-sm text-gray-400 italic">Sin gateways registrados.</p>}
                </div>

                {/* SECCIÓN 2: Sectores y GeoJSON */}
                <div className="space-y-3 pt-4 border-t border-gray-200">
                  <div className="flex justify-between items-center">
                    <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider flex items-center gap-2">
                      <MapIcon className="w-4 h-4" /> Sectores (Polígonos)
                    </h3>
                    <button className="text-xs font-medium text-agrogreen-600 hover:text-agrogreen-700 flex items-center gap-1 bg-agrogreen-50 px-2 py-1 rounded-md transition-colors">
                      <Upload className="w-3 h-3" /> Importar GeoJSON
                    </button>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    {sectores.map((sec: any) => (
                      <div key={sec.id} className="bg-white p-2 border border-gray-200 rounded-lg text-center shadow-sm">
                        <p className="font-bold text-sm text-gray-700">{sec.nombre}</p>
                        <p className="text-xs text-gray-400">{sec.cultivo}</p>
                      </div>
                    ))}
                  </div>
                </div>

                {/* SECCIÓN 3: Nodos por Asignar (Huérfanos) */}
                {nodosHuerfanos.length > 0 && (
                  <div className="space-y-3 pt-4 border-t border-red-100">
                    <h3 className="text-xs font-bold text-red-500 uppercase tracking-wider flex items-center gap-2">
                      <AlertTriangle className="w-4 h-4" /> Nodos Detectados sin Asignar
                    </h3>
                    {nodosHuerfanos.map((nodo: any) => (
                      <div key={nodo.id} className="bg-white p-3 rounded-xl border-2 border-red-200 shadow-sm flex justify-between items-center relative overflow-hidden">
                        <div className="absolute left-0 top-0 w-1 h-full bg-red-400"></div>
                        <div className="pl-2">
                          <p className="font-bold text-gray-800 text-sm">{nodo.id}</p>
                          <p className="text-xs text-gray-500">Ubicación desconocida</p>
                        </div>
                        <button 
                          onClick={() => setNodoAAsignar(nodo)}
                          className="bg-red-50 hover:bg-red-100 text-red-600 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 transition-colors"
                        >
                          <LinkIcon className="w-3 h-3" /> Asignar
                        </button>
                      </div>
                    ))}
                  </div>
                )}

                {/* SECCIÓN 4: Nodos Asignados */}
                <div className="space-y-3 pt-4 border-t border-gray-200">
                  <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider flex items-center gap-2">
                    <Cpu className="w-4 h-4" /> Nodos en Operación
                  </h3>
                  {nodosAsignados.map((nodo: any) => (
                    <div key={nodo.id} className={`bg-white p-3 rounded-xl border ${nodo.estado === 'ALERTA' ? 'border-red-200' : 'border-gray-100'} shadow-sm flex justify-between items-center`}>
                      <div>
                        <p className="font-bold text-gray-900 text-sm">{nodo.id}</p>
                        <p className="text-xs text-gray-500">{nodo.sectorNombre}</p>
                      </div>
                      <span className={`p-1.5 rounded-full ${nodo.estado === 'ALERTA' ? 'bg-red-100 text-red-700 animate-pulse' : 'bg-green-100 text-green-700'}`}>
                        {nodo.estado === 'ALERTA' ? <Activity className="w-4 h-4" /> : <CheckCircle2 className="w-4 h-4" />}
                      </span>
                    </div>
                  ))}
                </div>

              </div>
            )}

            {/* TAB: RESUMEN (Simplificado para el ejemplo) */}
            {activeTab === 'resumen' && (
              <div className="space-y-6 animate-in fade-in duration-300">
                 <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                    <p className="text-xs text-gray-500 mb-1">Salud del Cultivo</p>
                    <p className={`text-2xl font-bold ${nodosAlerta.length > 0 ? 'text-red-600' : 'text-green-600'}`}>
                      {nodosAlerta.length > 0 ? 'Alerta Detectada' : '100% Óptimo'}
                    </p>
                  </div>
              </div>
            )}
            
            {/* TAB: ADMIN */}
            {activeTab === 'administrativo' && (
              <div className="space-y-6 animate-in fade-in duration-300">
                 <p className="text-sm text-gray-500">Configuración del cliente aquí...</p>
              </div>
            )}

          </div>
        </div>
      </div>

      {/* MODAL DE ASIGNACIÓN RÁPIDA DE NODO */}
      {nodoAAsignar && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm rounded-xl">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="px-5 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
              <h3 className="font-bold text-gray-800 flex items-center gap-2">
                <LinkIcon className="w-4 h-4 text-agrogreen-600" /> Asignar Nodo
              </h3>
              <button onClick={() => setNodoAAsignar(null)} className="text-gray-400 hover:text-gray-600 transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>
            
            <div className="p-5 space-y-4">
              <div>
                <p className="text-xs text-gray-500">Dispositivo Seleccionado</p>
                <p className="font-mono font-bold text-lg text-gray-900">{nodoAAsignar.id}</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Selecciona el sector de instalación:</label>
                <select className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-agrogreen-500 text-sm">
                  <option value="">-- Seleccionar Sector --</option>
                  {sectores.map((sec: any) => (
                    <option key={sec.id} value={sec.id}>{sec.nombre} ({sec.cultivo})</option>
                  ))}
                </select>
              </div>

              <div className="pt-4 flex justify-end gap-3 border-t border-gray-100 mt-2">
                <button 
                  onClick={() => setNodoAAsignar(null)}
                  className="px-4 py-2 text-sm font-medium text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                >
                  Cancelar
                </button>
                <button 
                  className="px-4 py-2 text-sm font-medium text-white bg-agrogreen-600 hover:bg-agrogreen-700 rounded-lg transition-colors"
                >
                  Vincular Nodo
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}